<?php
require __DIR__.'/_init.php'; require __DIR__.'/_layout.php';
$id=max(0,(int)($_GET['id']??0));$q=db()->prepare('SELECT * FROM orders WHERE id=?');$q->execute([$id]);$o=$q->fetch();
if(!$o){http_response_code(404);$items=db()->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$items->execute([$id]);$items=$items->fetchAll();
