$labels=['recebido'=>'Recebido','em_analise'=>'Em análise','aguardando_cliente'=>'Aguardando cliente','aprovado'=>'Aprovado','em_producao'=>'Em produção','concluido'=>'Concluído','entregue'=>'Entregue','cancelado'=>'Cancelado'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$next=(string)($_POST['status']??'');$note=trim((string)($_POST['note']??''));if(isset($labels[$next])){try{$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$next,$id]);$pdo->prepare('INSERT INTO order_status_history(order_id,old_status,new_status,note,admin_id) VALUES(?,?,?,?,?)')->execute([$id,$o['status'],$next,$note?:null,$_SESSION['admin_id']??null]);$pdo->commit();flash('Pedido atualizado.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Não foi possível atualizar o pedido.','error');}}header('Location: order.php?id='.$id);exit;}
$itemsQ=db()->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$itemsQ->execute([$id]);$items=$itemsQ->fetchAll();
$p=db()->prepare('SELECT * FROM order_photos WHERE order_id=? ORDER BY id');$p->execute([$id]);$photos=$p->fetchAll();
$h=db()->prepare('SELECT h.*,a.name admin_name FROM order_status_history h LEFT JOIN admins a ON a.id=h.admin_id WHERE h.order_id=? ORDER BY h.created_at DESC,h.id DESC');$h->execute([$id]);$history=$h->fetchAll();
$phone=preg_replace('/\D/','',$o['customer_phone']);$wa='https://wa.me/'.$phone.'?text='.rawurlencode('Olá, '.$o['customer_name'].'! Sobre seu pedido '.$o['order_code'].' da F&J Artes Presentes: ');
admin_header('Pedido '.$o['order_code'],'orders');?>
<div class="actions" style="margin-bottom:16px"><a class="btn outline" href="orders.php">← Todos os pedidos</a><a class="btn primary" target="_blank" rel="noopener" href="<?=e($wa)?>">Conversar no WhatsApp ↗</a></div>
<?php if($items):?><section class="panel"><h2>Itens do pedido</h2><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Quantidade</th><th>Preço unitário</th><th>Total</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name'])?></td><td><?=$it['quantity']?></td><td>R$ <?=number_format((float)$it['unit_price'],2,',','.')?></td><td>R$ <?=number_format((float)$it['line_total'],2,',','.')?></td></tr><?php endforeach;?></tbody></table></div><p><strong>Total estimado: R$ <?=number_format((float)$o['total_amount'],2,',','.')?></strong></p></section><?php endif;?><div class="order-detail-grid"><section class="panel"><h2>Dados do cliente</h2><dl class="order-dl"><dt>Nome</dt><dd><?=e($o['customer_name'])?></dd><dt>WhatsApp</dt><dd><?=e($o['customer_phone'])?></dd><dt>E-mail</dt><dd><?=e($o['customer_email']?:'Não informado')?></dd><dt>Produto</dt><dd><?=e($o['product_name'])?> (<?= (int)$o['quantity']?>)</dd><dt>Texto da arte</dt><dd><?=nl2br(e($o['personalization_text']?:'Não informado'))?></dd><dt>Detalhes</dt><dd><?=nl2br(e($o['details']?:'Não informado'))?></dd><dt>Recebido em</dt><dd><?=e(date('d/m/Y H:i',strtotime($o['created_at'])))?></dd></dl></section>
<section class="panel"><h2>Gerenciar status</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Status<select name="status"><?php foreach($labels as $k=>$v):?><option value="<?=e($k)?>" <?=$o['status']===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label>Observação do histórico<textarea name="note" rows="3" placeholder="Ex.: cliente confirmou a arte..."></textarea></label><button class="btn primary">Salvar atualização</button></form></section></div>
<section class="panel"><h2>Fotos de referência (<?=count($photos)?>)</h2><?php if($photos):?><div class="order-photo-grid"><?php foreach($photos as $ph):?><a href="../<?=e($ph['file_path'])?>" target="_blank" rel="noopener"><img src="../<?=e($ph['file_path'])?>" alt="<?=e($ph['original_name'])?>"><small><?=e($ph['original_name'])?></small></a><?php endforeach;?></div><?php else:?><p class="muted">O cliente não enviou imagens.</p><?php endif;?></section>
<section class="panel"><h2>Histórico do pedido</h2><div class="order-history"><?php foreach($history as $row):?><div><strong><?=e($labels[$row['new_status']]??$row['new_status'])?></strong><small><?=e(date('d/m/Y H:i',strtotime($row['created_at'])))?> · <?=e($row['admin_name']??'Cliente/sistema')?></small><?php if($row['note']):?><p><?=e($row['note'])?></p><?php endif;?></div><?php endforeach;?></div></section>
<?php admin_footer();